"""Build the static reference from authored chapters and captured lab evidence."""
from pathlib import Path
from html import escape
import json, re, io, tokenize, keyword
ROOT=Path(__file__).resolve().parents[1]
CH=[]
def p(s): return '<p>'+s+'</p>'
def ul(items):return '<ul>'+''.join('<li>'+s+'</li>' for s in items)+'</ul>'
def note(title,s):return '<aside class="margin-note"><b>'+title+'</b>'+p(s)+'</aside>'
def table(headers,rows):return '<div class="table-scroll"><table><thead><tr>'+''.join('<th scope="col">'+s+'</th>' for s in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+s+'</td>' for s in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def highlight_python(s):
 try:
  offsets=[0]
  for line in s.splitlines(keepends=True): offsets.append(offsets[-1]+len(line))
  out=[]; cursor=0
  for token in tokenize.generate_tokens(io.StringIO(s).readline):
   cls={tokenize.STRING:'s',tokenize.NUMBER:'n',tokenize.COMMENT:'c'}.get(token.type)
   if token.type==tokenize.NAME and keyword.iskeyword(token.string): cls='k'
   if not cls: continue
   a=offsets[token.start[0]-1]+token.start[1]
   b=offsets[token.end[0]-1]+token.end[1]
   out.extend([escape(s[cursor:a]),'<span class="'+cls+'">'+escape(s[a:b])+'</span>']);cursor=b
  out.append(escape(s[cursor:]));return ''.join(out)
 except (tokenize.TokenError,IndentationError,IndexError): return escape(s)
def code(s,label='Python',file=None):
 raw=s.strip()
 rendered=highlight_python(raw) if label.startswith('Python') or 'app.py' in label else escape(raw)
 return '<figure class="code"><figcaption><span>'+label+'</span>'+('<a download href="../lab/'+file+'">Файл целиком ↓</a>' if file else '')+'</figcaption><pre><code>'+rendered+'</code></pre></figure>'
def shot(name,title,caption):return f'<figure class="evidence"><button class="zoom" data-image="../shots/{name}.png" aria-label="Увеличить: {title}"><img src="../shots/{name}.png" alt="{title}" loading="lazy" width="1440" height="1080"></button><figcaption><b>Кадр · {title}</b><p>{caption}</p><a href="../shots/{name}.png" target="_blank" rel="noreferrer">Открыть оригинал ↗</a></figcaption></figure>'
def case(title,task,answer):return '<div class="case"><span class="eyebrow">Разберите самостоятельно</span><h3>'+title+'</h3>'+task+'<details><summary>Проверить рассуждение</summary>'+answer+'</details></div>'
def source(url,title):return '<p class="source">Источник для уточнения: <a href="'+url+'" target="_blank" rel="noreferrer">'+title+' ↗</a></p>'
def add(slug,title,lead,sections,recap,quiz,links):CH.append(dict(slug=slug,title=title,lead=lead,sections=sections,recap=recap,quiz=quiz,links=links))
add('01-posle-deploy','После запуска: что происходит с приложением','Начинаем с жалобы на медленный API. Разбираем, каких данных не хватает разработчику после развёртывания и почему успешный запрос ещё не описывает состояние сервиса.',[
('local','Локальный запрос и работающий сервис',p('Мы написали обработчик <code>GET /products</code>: он получает товары и возвращает JSON. Локально рядом открыты терминал, редактор и отладчик. Когда возникает исключение, можно увидеть стек вызовов; когда результат неверен — поставить точку останова и посмотреть значения.')+p('После развёртывания приложение работает независимо от нашей проверки. Пользователи обращаются к разным экземплярам API; часть операций продолжается в очереди. Ошибка могла возникнуть ночью, а процесс с нужными данными к утру уже перезапустился. Вопрос «что происходит» превращается в вопрос «какие свидетельства сохранились».')+'''<div class="interactive architecture" data-architecture><div class="widget-head"><b>Где проходит запрос</b><div class="controls"><button data-mode="local" aria-pressed="true">Локально</button><button data-mode="production" aria-pressed="false">После deploy</button></div></div><div class="system-route"><span>Разработчик</span><i>→</i><span>FastAPI</span><i>→</i><span>Хранилище</span></div><p class="widget-detail" aria-live="polite">Один запрос. Терминал и состояние процесса доступны разработчику.</p></div>'''+p('Развёртывание, или <em>deploy</em>, — запуск выбранной версии программы в среде, где ею пользуются. Само наличие нескольких компонентов не делает систему наблюдаемой. Если они не фиксируют события и измерения, схема архитектуры не поможет восстановить конкретный сбой.')),
('quality','Четыре разных обещания пользователю',table(['Свойство','Что проверяем','Пример нарушения'],[['Доступность','Можно ли получить нужный ответ?','Сервис не отвечает или возвращает 503.'],['Производительность','Сколько времени и ресурсов требует работа?','Товары возвращаются за 3 секунды вместо 100 мс.'],['Надёжность','Сохраняется ли требуемое поведение во времени и при сбоях?','Периодически теряются фоновые задания.'],['Корректность','Соответствует ли результат смыслу операции?','HTTP 200 пришёл, но заказ не записан.']])+p('Эти свойства пересекаются. При тайм-ауте пользователь воспринимает слишком медленную операцию как недоступную. Поэтому нужно определить, что именно считаем успешным: код HTTP, содержимое ответа, запись заказа или завершение всей бизнес-операции.')+p('У <code>/health</code> в нашем стенде узкое обещание: процесс способен выполнить этот обработчик. Он не проверяет другие маршруты и не обращается к зависимости. Если <code>/health</code> отвечает 200, это ещё не свидетельство исправности <code>/products</code>.')),
('two-requests','Два ответа HTTP 200',shot('api-fast','Быстрый ответ настоящего FastAPI','Запущен сценарий fast. Верхняя строка показывает время на стороне браузера и внутри обработчика. Эти величины измерены в разных точках.')+shot('api-slow','Медленный ответ того же обработчика','Сценарий slow добавляет трёхсекундное ожидание зависимости. Код HTTP и бизнес-ответ остаются успешными; длительность меняется.')+p('В стенде мы управляем задержкой, поэтому можем повторить опыт. В реальной системе такой переключатель обычно отсутствует: придётся выяснять, какие условия совпали с задержкой. Повторный быстрый запрос после жалобы доказывает только то, что один запрос в этот момент выполнился быстро.')+case('Одна ручная проверка против истории',p('Из 1000 запросов пять вернули 500. Ваш единственный запрос завершился 200. Можно ли закрыть жалобу как неподтверждённую?'),p('Нет. Случайная ручная проверка легко не попадёт в редкую ошибку. Нужны данные за интервал жалобы, число запросов, число ошибок и критерий успеха. Даже доля 5 / 1000 = 0,5% описывает запросы, а не число разных пользователей.'))),
('evidence','Симптом, наблюдение и объяснение',p('Пользователь сообщает: «каталог иногда долго открывается». Это симптом. В измерениях видно: после 14:00 выросла длительность части запросов. Это наблюдение. Предположение «запросы ждут соединение с базой» — гипотеза, пока мы не измерили ожидание и не проверили альтернативы.')+table(['Уровень','Что можно написать в разборе'],[['Симптом','Пользователь ждёт каталог несколько секунд.'],['Наблюдение','В выборке есть два запроса дольше 3 секунд; их HTTP-статус 200.'],['Гипотеза','Задержка находится в зависимости или ожидании ресурса.'],['Проверка','Сопоставляем длительности этапов и события того же request_id.'],['Вывод','В учебном сценарии задержка внесена в dependency.wait; для настоящей системы нужны её собственные измерения.']])+p('CPU 95% может быть частью причины, следствием наплыва запросов или нормальным состоянием вычислительной задачи. Без временного контекста, нагрузки и влияния на пользователя объявлять CPU причиной рано.')),
('need','Что нужно сохранять до появления жалобы',p('После перезапуска нельзя получить прошлые значения из памяти исчезнувшего процесса. Если длительность операции не измерялась, детально восстановить её только по текущему коду тоже нельзя. Наблюдения нужно получать во время работы, хранить с отметкой времени и связывать с компонентом.')+ul(['Сколько операций произошло за выбранный интервал и какие результаты они дали.','Как распределялись длительности, а не только чему равно среднее.','Какие события сопровождали сбой и какой версии приложения они принадлежат.','Через какие этапы прошла конкретная операция.'])+p('Это и есть практическая причина перехода к мониторингу: регулярные измерения сохраняют контекст, которого нет у единичной проверки.'))],
['HTTP 200 описывает ответ протокола; бизнес-успех нужно определить отдельно.','Один запрос не характеризует весь сервис за прошедший день.','Причину подтверждают измерениями и проверкой гипотез.'],
('Каких данных не хватает жалобе «сегодня тормозит»?', 'Нужны хотя бы интервал времени, операция, частота/масштаб проявления, длительности и контекст запроса. Затем выбираем сигналы, которые смогут ответить на уточнённые вопросы.'),
[('https://sre.google/sre-book/monitoring-distributed-systems/','Google SRE · внешнее поведение и внутренние показатели')])
add('02-monitoring','Мониторинг: измерения и история','Определяем, что наблюдать, как читать временной ряд и почему график должен сопровождаться единицами, окном времени и областью измерения.',[
('process','От регулярного наблюдения к действию',p('<strong>Мониторинг</strong> — организованный процесс получения и анализа данных о работе системы. Мы выбираем показатели, регулярно собираем наблюдения, сохраняем историю и задаём условия, при которых требуется внимание.')+p('Например, каждую минуту проверяем длительность пользовательской операции. На графике видна динамика; правило обнаруживает устойчивое ухудшение; уведомление приходит человеку, который может вмешаться. Каждый участок нужен для своей работы. Красивый график без сохранённых данных не позволит вернуться к вчерашнему инциденту.')+'''<ol class="pipeline"><li><b>Измерить</b><span>Что произошло в программе</span></li><li><b>Сохранить</b><span>Значение и время</span></li><li><b>Сопоставить</b><span>Окно, группа, базовый уровень</span></li><li><b>Показать</b><span>График или таблица</span></li><li><b>Отреагировать</b><span>Правило и действие</span></li></ol>'''+p('Мониторинг может использовать метрики, журналы событий, внешние пробы и другие данные. Его нельзя отождествить с одной программой: Grafana показывает результаты запросов к источникам, а сами измерения возникают в приложениях и инфраструктуре.')),
('history','У одного числа может быть разная история',p('Значение «CPU = 80%» без дополнительных сведений трудно оценить. Возможно, нагрузка держится на этом уровне в течение часа и сервис соблюдает требования. Возможно, за минуту она выросла с 20% вместе с задержками. В обоих случаях последнее число одинаковое.')+'''<div class="interactive history" data-history><div class="widget-head"><b>CPU · два учебных временных ряда</b><div class="controls"><button data-series="steady" aria-pressed="true">Стабильная нагрузка</button><button data-series="spike" aria-pressed="false">Резкий рост</button></div></div><svg viewBox="0 0 680 240" role="img" aria-label="CPU в процентах за шесть наблюдений: последнее значение 80%"><g class="gridlines"><path d="M55 30H650M55 110H650M55 190H650"/></g><g class="axis-labels"><text x="10" y="35">100%</text><text x="20" y="115">50%</text><text x="28" y="195">0%</text><text x="55" y="223">09:00</text><text x="590" y="223">09:05</text></g><polyline class="history-line" points="55,65 174,62 293,59 412,64 531,60 650,62" fill="none" stroke-width="4"/><g class="history-dots"></g></svg><p class="widget-detail" aria-live="polite">78 → 80 → 82 → 79 → 81 → 80%. Последнее значение: 80%.</p><small>Учебные данные для сравнения формы графика; это не измерения CPU стенда.</small></div>'''+p('Временной ряд объединяет наблюдения одной величины, упорядоченные по времени. Важно сохранить смысл серии: CPU какого процесса или узла, как вычислен процент, какова частота измерений. Нельзя склеить данные разных объектов и продолжать читать линию как один процесс.')+source('https://prometheus.io/docs/concepts/data_model/','Prometheus · Data model')),
('scope','Четыре области наблюдения',table(['Область','Показатели','Вопрос'],[['Приложение','Запросы, ошибки, длительности, активные запросы','Ухудшилось ли обслуживание пользователей?'],['Фоновые задания','Время ожидания, выполнения, повторы, отказы','Почему документ ещё не готов после HTTP 202?'],['Зависимости','Занятые соединения, ожидание пула, длительность обращения','На каком внешнем ресурсе ждёт приложение?'],['Инфраструктура','CPU, память, диск, сеть','Есть ли ограничение ресурсов или неисправность среды?']])+p('Наблюдать только сервер недостаточно: очередь может расти при свободном CPU, если обработчики ждут внешнее API. Наблюдать только длительность HTTP тоже недостаточно: пользователь получил 202, а задание осталось в очереди. Область измерения должна соответствовать обещанной операции.')),
('windows','Окно времени меняет смысл ответа',p('«Ошибок пять» — неполное описание. Пять за секунду при десяти запросах и пять за сутки при миллионе — разные ситуации. Для доли ошибок числитель и знаменатель должны относиться к одним маршрутам, одному интервалу и одной системе классификации.')+code('error_ratio = failed_requests / all_requests\nerror_percent = error_ratio * 100','Формула · значения за одно окно')+p('Если запросов не было, знаменатель равен нулю. Это отсутствие наблюдений о пользовательских запросах, а не доказательство нулевой доли ошибок. В дашборде нужно различать «0 ошибок из 100» и «нет запросов / нет данных».')+case('Две реплики API',p('Первая обработала 10 запросов, из них 5 ошибочных. Вторая — 990 запросов без ошибок. Чему равна общая доля ошибок?'),p('5 / 1000 = 0,5%. Среднее между процентами 50% и 0% дало бы 25%, что неверно: группы имеют разный размер. Сначала складываем совместимые количества, затем делим.'))),
('blackbox','Внешняя проба и внутренние показатели',p('<strong>Black-box monitoring</strong> проверяет поведение через внешний интерфейс: доступна ли страница, проходит ли операция, сколько она занимает. <strong>White-box monitoring</strong> использует сведения изнутри системы: состояние очереди, число соединений, время этапов обработчика.')+p('Внешняя проба полезна тем, что проходит часть того же пути, что пользователь: DNS, сеть, TLS и балансировщик. Внутренний показатель может точнее локализовать задержку, но не заметить проблему на пути до приложения. Для диагностики нужны оба взгляда.')+note('Проверяйте именно то, что обещает probe','Проверка /health не равна проверке оформления заказа. Внешняя проба может выполнять бизнес-сценарий, а внутренний health endpoint — проверять зависимости. Различие определяется точкой наблюдения и содержанием проверки, а не названием URL.'))],
['У любого показателя есть объект, единица измерения, интервал и способ расчёта.','Для общей доли складываем количества до деления.','Нет данных и нулевое значение требуют разных объяснений.'],
('Почему график памяти не отвечает на вопрос «успешно ли создан заказ»?','Он описывает ресурс процесса. Для ответа нужен критерий завершения бизнес-операции и наблюдение, подтверждающее этот результат.'),
[('https://sre.google/sre-book/monitoring-distributed-systems/','Google SRE · Monitoring Distributed Systems')])
add('03-observability','Наблюдаемость и телеметрия','Разбираем, какие данные позволяют исследовать неожиданный сбой, как связать наблюдения и где проходит граница между фактом и гипотезой.',[
('question','Новый вопрос к работающей системе',p('В дашборде есть CPU, память и общий поток запросов. Пользователь сообщает: отчёты с большим числом строк иногда формируются долго, а обычные отчёты работают быстро. Ни одна готовая панель не выделяет этот сценарий. Нужно исследовать данные по дополнительным признакам, а не только посмотреть, загорелся ли установленный порог.')+p('<strong>Наблюдаемость</strong> — способность получать представление о внутреннем поведении системы по доступным внешним сигналам. Для инженера это означает возможность проверить гипотезу: выделить операции, сопоставить события и выяснить, какие этапы заняли время.')+p('Эта способность зависит от того, какие данные были созданы и сохранены. Если размер отчёта нигде не фиксировался, построить точную связь между ним и задержкой задним числом не получится. Дополнительное наблюдение появится только после изменения инструментации и новых запусков.')+source('https://opentelemetry.io/docs/concepts/observability-primer/','OpenTelemetry · Observability primer')),
('relation','Мониторинг и наблюдаемость работают вместе',table(['Работа инженера','Пример'],[['Наблюдать заранее выбранный показатель','Проверять, не растёт ли доля неуспешных операций.'],['Обнаружить изменение','Получить сигнал об устойчивом ухудшении.'],['Уточнить область','Отфильтровать версию, маршрут и экземпляр.'],['Проверить объяснение','Сопоставить задержку с ожиданием зависимости у конкретных операций.'],['Улучшить наблюдение','Добавить недостающее измерение и повторить опыт.']])+p('Разделение «мониторинг отвечает что, наблюдаемость отвечает почему» удобно как первое приближение, но слишком жёстко. Хороший мониторинг участвует в поиске причины. Несколько трасс без контекста не гарантируют ответ «почему». Мы оцениваем достаточность данных для вопроса, а не присваиваем продукту один из двух ярлыков.')),
('telemetry','Какие данные система сообщает о себе',p('<strong>Телеметрия</strong> — данные о поведении системы, полученные во время её работы. В первой теме мы используем три формы: числовые измерения, записи событий и путь отдельной операции. Они по-разному сохраняют контекст.')+'''<div class="signal-cards"><div><span class="signal-icon">∑</span><h3>Метрики</h3><p>Числа и распределения: частота, доля, длительность, размер.</p><code>errors / requests</code></div><div><span class="signal-icon">{ }</span><h3>Логи</h3><p>События: время, действие, результат, контекст ошибки.</p><code>event=dependency_timeout</code></div><div><span class="signal-icon">↳</span><h3>Трассы</h3><p>Связанные этапы: путь и длительности одной операции.</p><code>request → wait → query</code></div></div>'''+p('Данные не возникают из названий инструментов. Программа должна измерить длительность, записать событие или создать этап трассы. Добавление такого кода и подключение библиотек называют <strong>инструментацией</strong>. Автоматическая инструментация покрывает типовые операции; бизнес-смысл часто приходится добавлять самостоятельно.')+shot('otel-signals','Раздел Signals в официальной документации OpenTelemetry','Официальная страница показана для навигации по источнику. В справочнике сначала изучаются metrics, logs и traces; статусы других направлений проверяйте в документации.')+p('Baggage переносит пары ключ–значение вместе с контекстом операции. Оно не является самостоятельным хранилищем событий. Профили показывают распределение затрат по выполняемому коду. Эти направления понадобятся позже, после понимания трёх основных форм данных.')),
('correlation','Время и идентификатор связывают события',p('Две строки с одинаковой секундой могли относиться к разным запросам. На сервере одновременно выполняется много операций. Поэтому для поиска событий конкретного запроса нужен устойчивый идентификатор, который сохраняется во всех связанных записях.')+code('''{
  "timestamp": "2026-09-15T12:00:00.000+00:00",
  "service": "products-api",
  "request_id": "f81c…",
  "event": "request_completed",
  "status": 500
}''','Учебная структура события')+p('Время нужно для размещения события на общей шкале; идентификатор — для связи событий одной операции. В распределённой трассировке контекст обычно содержит trace ID и span ID. Наш первый стенд использует один request_id внутри процесса: это начальная модель, а не реализация всех правил OpenTelemetry.')+note('Контекст имеет цену','Произвольный user_id или request_id в метрике создаёт множество отдельных рядов. Такие подробности обычно сохраняют в событиях и трассах. В метриках для группировки выбирают ограниченные признаки, например шаблон маршрута и класс ответа. Кардинальность разберём в следующем модуле.')),
('limits','Три источника данных тоже могут ошибаться',p('Телеметрия описывает то, что действительно измерено и доставлено. Логи могут потеряться при аварии; трассы могут отбираться сэмплированием; метрики приходят с интервалом и зависят от доступности цели. Время разных машин может расходиться. Отсутствие события в сохранённых данных не всегда означает, что событие не происходило.')+case('Наблюдение или доказательство?',p('После релиза выросла задержка. В тот же момент вырос CPU. Инженер пишет: «Причина — новый алгоритм». Чего не хватает?'),p('Нужно отличить изменение алгоритма от роста трафика, изменения данных и других факторов. Проверьте сравнимые операции, профили или этапы выполнения, а также обратимость эффекта при контролируемом изменении. Одновременное изменение двух графиков — основание для гипотезы, но ещё не доказательство причины.')))],
['Наблюдаемость ограничена собранными данными.','Инструментация создаёт измерения и контекст, которые затем собирают системы телеметрии.','Идентификатор связывает события одной операции; отметка времени помещает их в историю.'],
('Можно ли восстановить SQL конкретного запроса по общему счётчику ошибок?','Нет: агрегация не сохраняет такой контекст. Нужны события или трасса с нужной детализацией и действующие правила хранения этих данных.'),
[('https://opentelemetry.io/docs/concepts/instrumentation/','OpenTelemetry · Instrumentation'),('https://opentelemetry.io/docs/concepts/context-propagation/','OpenTelemetry · Context propagation')])
add('04-metrics','Метрики: числа, интервалы и распределения','Переходим от отдельных ответов к масштабу проблемы. На реальном наборе из двадцати запросов считаем долю ошибок, среднее и p95 и разбираем, какие сведения исчезают при агрегации.',[
('measurement','Что именно называется измерением',p('Отправим запрос и измерим время от отправки до получения ответа. Результат — одно наблюдение длительности. Если повторять опыт, появится набор наблюдений. Его можно представить отдельными значениями, суммой, количеством или распределением по диапазонам.')+p('<strong>Метрика</strong> описывает измеряемую характеристику и способ представления её значений. Например, количество завершённых запросов, текущая длина очереди или распределение длительности HTTP-операций. Полезное имя не заменяет описание: нужно знать точку измерения, единицы и набор учитываемых операций.')+table(['Величина','Единица','Что нужно уточнить'],[['Завершённые запросы','запросы','Какие маршруты и статусы? С какого момента считается?'],['Поток запросов','запросы/с','За какое окно вычислена скорость?'],['Длительность','секунды','На клиенте или внутри обработчика? Учитываются ошибки?'],['Очередь','задания','Готовые к обработке, выполняемые или все вместе?']])+p('В Prometheus основой хранения служат временные ряды. В этом введении рассматриваем обычные числовые наблюдения. Подробная модель, включая histogram samples, появится после знакомства с типами метрик.')),
('counter','Количество с запуска и количество за интервал',p('Значение счётчика 15 000 означает, что к моменту наблюдения инструмент насчитал 15 000 событий в своей области учёта. Оно не означает 15 000 событий за последнюю минуту. Для интервала нужны по крайней мере сведения об изменении счётчика.')+code('''12:00:00    requests_total = 15000
12:00:10    requests_total = 15240

240 запросов / 10 секунд = 24 запроса/с''','Учебный пример · без перезапуска процесса')+p('В этом примере получена средняя скорость за десять секунд. Между отсчётами запросы могли приходить неравномерно. Если процесс перезапустился и счётчик обнулился, простое вычитание даст неправильный результат. Позже для счётчиков мы разберём функции, учитывающие сбросы.')+p('Состояние вроде длины очереди ведёт себя иначе: оно может увеличиваться и уменьшаться без перезапуска. Нельзя применять к каждому числу одинаковый расчёт только потому, что оно находится на графике.')),
('experiment','Двадцать запросов нашего стенда',p('В сохранённом прогоне сценарии заданы заранее: 17 быстрых, два медленных и одна ошибка. Это управляемый опыт, а не случайная выборка производственного трафика. Длительности измерены; последовательность сценариев повторяется, но точные времена на вашей машине будут отличаться.')+table(['Показатель','Из сохранённого прогона','Как читать'],[['Всего запросов','20','Все запросы experiment.py, включая ошибочный'],['HTTP 500','1 из 20 = 5%','Доля запросов; число пользователей не измеряется'],['Дольше 1000 мс','2 из 20 = 10%','Порог выбран для этого опыта'],['Среднее время клиента','379,781 мс','Сумма всех длительностей / 20'],['p95, nearest rank','3024,333 мс','19-е значение отсортированного списка']])+p('<a href="../lab/results/requests.csv" download>Скачать исходные 20 строк CSV</a> · <a href="../lab/results/summary.json" download>Скачать расчёт</a>. Время клиента включает путь запроса до приложения и обратно. Внутреннее время обработчика сохраняется отдельным столбцом <code>handler_ms</code>.')),
('percentile','Почему среднее не описывает редкие задержки',p('Большинство запросов занимает около 85 мс, но два ждут около трёх секунд. Среднее 380 мс не похоже ни на обычный быстрый ответ, ни на задержанный. Оно полезно для суммарных затрат, но не заменяет представление о распределении.')+p('<strong>Перцентиль</strong> задаёт положение в упорядоченной выборке. Здесь используем метод ближайшего ранга: для p95 берём позицию <code>ceil(0.95 × n)</code>, считая с единицы. При n = 20 это позиция 19. Другие методы могут интерполировать между наблюдениями; результат зависит от принятого метода.')+'''<div class="interactive quantile" data-quantile><div class="widget-head"><b>20 измерений · время клиента</b><div class="controls"><button data-order="original" aria-pressed="true">Порядок запросов</button><button data-order="sorted" aria-pressed="false">По длительности</button></div></div><div class="duration-chart" aria-label="Реальные длительности двадцати запросов"></div><p class="widget-detail" aria-live="polite">Переключите порядок, чтобы найти 19-е значение — p95 по методу ближайшего ранга.</p><small>Высота пропорциональна длительности: от 0 мс у основания до 3024,333 мс у вершины самого высокого столбца. Столбцы подписаны номером исходного запроса; выберите столбец для точного значения.</small></div>'''+p('p95 относится к выбранным операциям и окну. Он не означает, что 95% пользователей довольны. Один человек может отправить сотню запросов, а другой — один. В небольшой выборке несколько наблюдений сильно меняют перцентиль; для оценки реального сервиса нужны представительная нагрузка и история.')+note('Среднее p95 разных экземпляров','Нельзя получить общий p95 простым средним от p95 двух реплик. Перцентили не сохраняют исходное распределение. Для объединения используют совместимые распределения, а затем вычисляют общий перцентиль. Механизм разберём на гистограммах.')),
('loss','Какие подробности теряются',p('Два набора могут иметь одинаковое количество запросов и ошибок, но разные причины. В одном сбои происходят в одном экземпляре, в другом — равномерно по всем. Общая сумма эту разницу скрывает. Разбиение по ограниченному набору признаков позволяет сохранить полезный контекст, но не подробности каждого события.')+case('Чего нет в числе 5%?',p('Известно, что за пять минут 5% запросов вернули 500. Можно ли определить по этому числу exception, список пользователей и этап, где возникла ошибка?'),p('Нет. Для исключения и контекста нужен журнал, для времени этапов — измерения этапов или трасса. Чтобы получить число разных пользователей, нужен отдельно определённый учёт; процент запросов нельзя автоматически переводить в процент людей.'))+p('Метрики наблюдения не заменяют журнал денежных операций. Сбор может пропустить события до следующего опроса, процесс может перезапуститься, значения могут быть агрегированы или оценены. Для финансового учёта нужен механизм, гарантирующий требуемую точность каждой операции.'))],
['Количество, скорость и доля — разные величины.','Перцентиль зависит от выборки, окна, точки измерения и метода.','Агрегация уменьшает детализацию: общий показатель не восстанавливает отдельные события.'],
('Было 100 запросов, 4 ошибки. После этого пришло ещё 900 запросов без ошибок. Доля осталась 4%?','За объединённый интервал доля равна 4/1000 = 0,4%. За первое окно она была 4%. Всегда указывайте, какие запросы входят в знаменатель.'),
[('https://prometheus.io/docs/concepts/metric_types/','Prometheus · Metric types'),('https://prometheus.io/docs/practices/histograms/','Prometheus · Histograms and summaries')])
add('05-logs','Логи: событие, контекст и исключение','Учимся читать структурированную запись, связывать события одного запроса и отличать стек исключения от распределённой трассы.',[
('event','Одна запись отвечает за одно событие',p('Счётчик ошибок сообщает масштаб, но не сохраняет описание каждой ошибки. <strong>Лог</strong> — запись о произошедшем событии. В минимальном полезном варианте в ней есть время и содержание; в рабочем сервисе также нужны компонент, уровень и контекст.')+p('Фраза <code>Request processed</code> показывает, что выполнение дошло до строки логирования. Без статуса, маршрута, времени и идентификатора мы не знаем, какой запрос обработан и каков его результат. Поэтому сначала определяем, какие вопросы должна закрывать запись, затем выбираем поля.')+'''<div class="interactive log-anatomy" data-log><div class="widget-head"><b>Структурированный лог по полям</b></div><div class="log-fields"><button data-field="timestamp">timestamp</button><button data-field="level">level</button><button data-field="service">service</button><button data-field="event">event</button><button data-field="status">status</button><button data-field="request_id">request_id</button><button data-field="duration_ms">duration_ms</button></div><pre><code>{"service":"products-api","event":"request_completed",
 "status":500,"request_id":"f81c…","duration_ms":80.6}</code></pre><p class="widget-detail" aria-live="polite">Выберите поле: увидите, на какой вопрос оно отвечает и чего не гарантирует.</p></div>'''),
('structure','Структура упрощает поиск',p('В свободной строке «ошибка базы у запроса ...» контекст приходится извлекать из текста. В JSON можно отобрать <code>event = request_completed</code> и <code>status = 500</code>, затем сгруппировать по сервису. Это не делает JSON автоматически хорошим логом: значения и названия полей должны быть последовательными.')+code('''logger.info(json.dumps({
    "event": "request_completed",
    "route": "/products",
    "status": status,
    "duration_ms": elapsed * 1000,
    "request_id": request_id,
}))''','Python · формирование события','app.py')+p('<code>logger.info</code> записывает сообщение через систему логирования Python; <code>json.dumps</code> превращает словарь в строку JSON. Здесь показан смысл полей. Полная программа дополнительно ставит временную отметку, сохраняет события для лаборатории и обрабатывает исключение.')+p('Единицы фиксируем в имени или схеме: <code>duration_ms</code> измеряется в миллисекундах. Число 80 без единицы допускает слишком много трактовок. Время события в стенде записывается с часовым поясом UTC; браузер и Grafana могут показывать локальное время.')),
('exception','Читаем настоящий traceback',shot('api-error','Ошибка 500 и Python traceback','Кадр снят после сценария error. Исключение TimeoutError действительно поднято и перехвачено в приложении. Текст прямо указывает, что зависимость моделируется.')+p('<strong>Traceback</strong> в Python показывает стек вызовов, приведший к исключению. Читать удобно от последней строки: там тип исключения и сообщение. Затем выше смотрим файл и строку, в которой ошибка возникла. Предыдущие кадры объясняют, как выполнение дошло до этого места.')+code('''try:
    raise TimeoutError("Simulated dependency timeout")
except TimeoutError:
    logger.exception("dependency_timeout request_id=%s", request_id)''','Python · exception внутри except','app.py')+p('<code>logger.exception</code> добавляет сведения о текущем исключении, поэтому его вызывают при обработке ошибки. Клиенту можно вернуть краткий результат, а подробности сохранить для диагностики. Возвращать весь внутренний стек пользователю для работы телеметрии не требуется.')+note('Traceback и trace','Стек исключения описывает цепочку вызовов в месте ошибки. Распределённая трасса связывает этапы операции и их интервалы времени, в том числе между сервисами. В успешной медленной операции traceback может вообще отсутствовать, а трасса всё равно полезна.')),
('count','Можно ли посчитать метрики из логов',p('Да: если каждая нужная операция записана ровно один раз и содержит достаточные поля, из журнала можно посчитать количество, долю ошибок и распределение длительностей. Неверно утверждать, что логи принципиально не подходят для численных вопросов. Цена и ограничения зависят от объёма и системы запросов.')+p('Проблемы появляются, когда один запрос создаёт несколько строк, записи дублируются при доставке, часть событий потеряна или длительность отсутствует. Тогда «количество строк с ERROR» не равно «количество неуспешных запросов». Для расчёта нужно определить событие учёта и обработку дубликатов.')+case('Почему grep ERROR недостаточно',p('Один запрос сделал три повтора и завершился успешно. Каждый повтор записал ошибку. Второй запрос упал без повторов. В журнале четыре ERROR. Сколько неуспешных запросов?'),p('По условию один. Количество ошибочных попыток — четыре, количество неуспешных запросов — одно. Для разных вопросов нужны разные события и явная связь попытки с запросом.'))),
('context','Сохраняем нужные подробности',p('Лог полезен, когда из него понятно, что случилось, где и к какой операции относится запись. Полный текст пользовательского документа или заголовок Authorization обычно не помогают ответить на этот вопрос. Для учебных материалов используются только синтетические данные; в рабочем сервисе состав полей согласуют с требованиями хранения и доступа.')+p('Уровень <code>ERROR</code> не определяет масштаб. Один и тот же тип ошибки может возникнуть один раз за месяц или на каждом запросе. Поэтому контекст отдельной записи сопоставляют с количеством операций за интервал.'))],
['Полезное событие содержит время, компонент, действие и контекст.','Число строк с ERROR может отличаться от числа ошибочных операций.','Traceback локализует исключение в коде; для пути операции нужны дополнительные данные.'],
('Как найти лог выбранного запроса среди сотни одновременных?', 'По его request_id или trace_id при условии, что идентификатор записан в нужных событиях. Одного совпадения времени недостаточно.'),
[('https://docs.python.org/3/library/logging.html','Python · logging'),('https://docs.python.org/3/library/traceback.html','Python · traceback'),('https://opentelemetry.io/docs/concepts/signals/logs/','OpenTelemetry · Logs')])
add('06-traces','Трассы: где операция потратила время','Разбираем spans, общую временную шкалу и вложенность. Отдельно рассматриваем ожидание очереди, параллельную работу и границы HTTP-запроса.',[
('path','Операция проходит несколько этапов',p('Ответ занял три секунды. Мы уже знаем длительность целиком, но не знаем, сколько из неё пришлось на проверку входа, ожидание зависимости и подготовку ответа. Если для этапов сохранить начало и длительность, появится временная картина операции.')+p('<strong>Трасса</strong> (trace) связывает этапы одной логической операции. Отдельный интервал работы называется <strong>span</strong>. Обычно у span есть имя, время начала и завершения, идентификатор и связь с родительским span. Дополнительные атрибуты описывают выполняемую работу.')+p('Трасса полезна и в одном сервисе. Распределённой она становится, когда связывает работу нескольких компонентов. Для этого контекст передаётся при вызовах: одинаковые названия маршрутов или совпадение времён сами по себе не создают такой связи.')),
('waterfall','Читаем временную шкалу',p('Каждая полоса ниже начинается в своём месте на общей оси времени. Длина показывает длительность. Полосы не следует мысленно складывать без проверки: дочерние spans уже входят в родительский, а параллельные интервалы перекрываются.')+'''<div class="interactive waterfall" data-waterfall><div class="widget-head"><b>Этапы настоящего slow-запроса</b><div class="controls"><button data-trace-step="next">Следующий этап →</button><button data-trace-step="reset">Сначала</button></div></div><div class="waterfall-axis"><span>0 мс</span><span class="trace-end">≈ 3020 мс</span></div><div class="waterfall-rows"></div><p class="widget-detail" aria-live="polite">Выберите этап, чтобы сопоставить его с общим временем обработчика.</p><small>Данные из events.json. Это измеренные ручные spans учебного процесса, не выгрузка из OpenTelemetry.</small></div>'''+p('У нашего slow-запроса основное время приходится на <code>dependency.wait</code>. Имя этапа и исходный код показывают, что это управляемое ожидание. В настоящем приложении такой span потребуется разделить: ожидание свободного соединения, сетевой вызов, выполнение запроса. Иначе общая полоса «database» оставляет несколько возможных причин.')+shot('api-slow','Измеренные этапы slow-запроса в учебной консоли','Сопоставьте суммарное время с полосой dependency.wait. Небольшая разница между суммой этапов и временем обработчика включает работу между замерами.')),
('parallel','Вложенность не равна сумме',table(['Сценарий','Измеренные интервалы','Как читать'],[['Последовательно','A: 0–200 мс; B: 200–500 мс','Общее время 500 мс; интервалы не перекрываются.'],['Параллельно','A: 0–200 мс; B: 0–500 мс','Общее время до завершения обоих — 500 мс, не 700.'],['Родитель и ребёнок','request: 0–500 мс; DB: 100–400 мс','300 мс DB уже входят в 500 мс request.']])+p('Вложенные spans помогают понять структуру вызовов, но не показывают автоматически собственное время каждой функции. Чтобы определить время вне дочерних операций, нужно учесть объединение их интервалов. Простое вычитание суммы перекрывающихся spans может дать бессмысленный результат.')+case('Две зависимости',p('API одновременно вызвал Redis на 40 мс и внешнее API на 900 мс, затем потратил 20 мс на ответ. При указанных условиях сколько заняла операция?'),p('Около 920 мс, если обе ветви начались вместе и других затрат нет. 40 мс Redis перекрываются с работой внешнего API. Ускорение Redis до 5 мс почти не изменит критический путь.'))),
('queue','HTTP-ответ и фоновая операция',p('Маршрут <code>POST /reports</code> может положить задание в очередь и вернуть 202 за 40 мс. Формирование PDF затем длится пять секунд. Нельзя рисовать фоновую задачу внутри сорокамиллисекундного HTTP-span, как будто ответ ожидал её завершения.')+p('Для всего пользовательского сценария нужны отдельные временные границы: принятие задания, постановка в очередь, начало обработки и готовность результата. Контекст из сообщения помогает связать производителя и потребителя. В зависимости от модели могут использоваться родительские связи или span links.')+'''<div class="queue-timeline"><div><b>HTTP</b><span>принять → поставить → 202</span><em>0–40 мс</em></div><div><b>Очередь</b><span>ожидать свободный worker</span><em>40–1200 мс</em></div><div><b>Worker</b><span>прочитать → создать PDF → сохранить</span><em>1200–6200 мс</em></div></div>'''+p('Это схема с учебными числами. Она показывает, почему длительность HTTP, время ожидания очереди и время до готовности отчёта — три разные метрики. Если измерять только API, задержка фоновой обработки может остаться незамеченной.')),
('sampling','Одна трасса и вся система',p('Длинный span показывает, где время потратила выбранная операция. Он не доказывает, что остальные запросы ведут себя так же. Для масштаба возвращаемся к метрикам и сравниваем несколько трасс: быстрые и медленные, до изменения и после него, с одинаковой операцией.')+p('При большом потоке могут сохранять лишь часть трасс — это <strong>сэмплирование</strong>. Если стратегия отбора неизвестна, нельзя по ста сохранённым медленным трассам заключить, что 100% запросов медленные. Трассы могли специально отбираться по задержке.')+note('Пустой участок на шкале','Он может означать реальное ожидание или участок без инструментации. По одной пустоте нельзя точно определить действие. Нужны измерение ожидания, события или более подробные spans.'))],
['Полоса span показывает интервал, а не отдельный слагаемый общей длительности.','Фоновая задача может завершиться значительно позже HTTP-ответа.','Одна трасса локализует выбранную операцию; масштаб проверяется отдельно.'],
('span DB занимает 2800 мс. Доказано ли, что SQL медленно выполняется на сервере базы?', 'Нет. Если границы span включают ожидание пула или сеть, большая часть времени могла уйти туда. Нужны отдельные измерения или события, разделяющие эти этапы.'),
[('https://opentelemetry.io/docs/concepts/signals/traces/','OpenTelemetry · Traces'),('https://opentelemetry.io/docs/concepts/sampling/','OpenTelemetry · Sampling')])
add('07-rassledovanie','Кейс: API иногда отвечает медленно','Проводим расследование по шагам. Отделяем масштаб от контекста одного запроса, проверяем альтернативы и составляем вывод с границами достоверности.',[
('report','Исходное сообщение',p('В 14:20 приходит жалоба: «список товаров иногда загружается несколько секунд». Ручная проверка разработчика проходит быстро. В общей панели нет всплеска ошибок. У нас ещё нет основания ни закрыть жалобу, ни обвинить базу данных.')+p('Сначала уточняем интервал, маршрут и наблюдаемое поведение. Замедлилась загрузка страницы целиком или ответ API? Какой браузер и регион? Есть ли request_id? Повторяется ли задержка у одной операции? Эти вопросы определяют область поиска, а не служат формальностью перед открытием Grafana.')+note('Учебный инцидент','Дальше используются явно заданные данные кейса. Они нужны для тренировки рассуждения и не выдаются за состояние реального сервера. Измеренный опыт FastAPI отдельно разобран в главе 1.9.')),
('steps','Открываем сведения последовательно',p('Ниже каждый новый факт должен либо сузить гипотезу, либо показать, какого наблюдения не хватает. Перед открытием следующего шага сформулируйте, что вы можете утверждать сейчас.')+'''<div class="interactive investigation" data-investigation><div class="widget-head"><b>Материалы инцидента /products</b><span class="step-count">1 / 5</span></div><h3 class="finding-title">Жалоба: иногда 4–5 секунд</h3><p class="finding-fact">Один повторный запрос прошёл за 180 мс.</p><div class="finding-columns"><div><b>Что известно</b><p class="finding-known">Одна проверка быстрая. Частота замедлений неизвестна.</p></div><div><b>Следующий вопрос</b><p class="finding-question">Есть ли распределение длительностей за интервал жалобы?</p></div></div><div class="controls"><button data-investigate="prev" disabled>← Назад</button><button data-investigate="next">Следующее свидетельство →</button></div></div>'''+p('Последовательное уточнение защищает от преждевременного вывода. «Ошибок нет» не отменяет проблему производительности. «CPU в норме» не означает отсутствия ожидания. «Пул занят» не объясняет, почему соединения удерживаются долго.')),
('chain','От найденного участка к проверяемой причине',p('В кейсе запросы задерживаются перед получением соединения. Это локализует ожидание, но оставляет несколько гипотез: вырос параллелизм, уменьшился пул, соединения не возвращаются, транзакции стали длиннее. Увеличить пул — возможное вмешательство, но без проверки оно может перегрузить базу.')+table(['Гипотеза','Чем проверять','Что опровергнет'],[['Резко вырос параллелизм','Число активных запросов и занятых соединений','При сопоставимой нагрузке задержки появились только после изменения кода.'],['Утечка соединений','Получение/возврат соединений; длительность удержания','Соединения возвращаются, а ожидание совпадает с долгими SQL.'],['Долгая транзакция','Длительность транзакций и их владельцы','Транзакции короткие, но сам пул уменьшился.'],['Слишком маленький пул','История конфигурации и тест при контролируемой нагрузке','При восстановлении конфигурации проблема сохраняется.']])+p('Причина подтверждается согласованной цепочкой: изменение → механизм → наблюдаемый эффект. Контролируемый повтор, откат или исправление даёт дополнительное свидетельство. После вмешательства проверяем не только исчезновение одного длинного span, но и поведение сервиса на нужном интервале.')),
('signals','Выберите данные под вопрос',p('В каждой строке выберите полезные сигналы. Может подойти несколько вариантов: важен состав данных, а не название системы хранения.')+'''<div class="signal-exercise" data-signal-exercise><fieldset data-answer="metrics,logs"><legend>1. Доля завершившихся ошибкой запросов за 5 минут</legend><label><input type="checkbox" value="metrics"> Метрики</label><label><input type="checkbox" value="logs"> Логи с одним событием на запрос</label><label><input type="checkbox" value="traces"> Случайная неполная выборка трасс</label><p hidden class="feedback">Метрики или полный подходящий журнал. Неполная выборка трасс без учёта отбора не даёт точной доли всех запросов.</p></fieldset><fieldset data-answer="logs,traces"><legend>2. Что случилось внутри выбранного запроса</legend><label><input type="checkbox" value="metrics"> Общий счётчик запросов</label><label><input type="checkbox" value="logs"> Логи с request_id</label><label><input type="checkbox" value="traces"> Трасса с событиями и атрибутами</label><p hidden class="feedback">Логи и трасса с нужным контекстом. Общий счётчик не сохраняет историю отдельного запроса.</p></fieldset><fieldset data-answer="traces"><legend>3. Какие из нескольких этапов перекрывались во времени</legend><label><input type="checkbox" value="metrics"> Суммарная длительность всех запросов</label><label><input type="checkbox" value="logs"> Лог без начала и конца этапов</label><label><input type="checkbox" value="traces"> Spans на общей временной оси</label><p hidden class="feedback">Интервалы spans показывают перекрытие. Подробный журнал границ тоже мог бы помочь, но в условии таких полей у него нет.</p></fieldset><button class="primary" data-check-signals>Проверить выбор</button><p class="exercise-score" role="status"></p></div>'''),
('report-template','Пишем итог расследования',code('''Симптом: пользователи ждут /products несколько секунд.
Интервал и область: указать время, версию, экземпляры и маршруты.
Масштаб: количество операций и доля медленных за тот же интервал.
Наблюдения: какие измерения и события подтверждены.
Гипотеза: какой механизм мог вызвать наблюдаемый эффект.
Проверка: что изменили или сопоставили; результат.
Вывод: что установлено, что пока остаётся неизвестным.
После исправления: какие показатели проверили повторно.''','Шаблон инженерного разбора')+p('Такой отчёт отделяет измерение от интерпретации. Фраза «база тормозила» не даёт читателю проверить рассуждение. Фраза «выбранный запрос ждал соединение 2,8 с; SQL занял 35 мс» уже указывает конкретный участок и следующий вопрос.'))],
['Начинаем с области и масштаба проблемы.','Длинный участок трассы сужает поиск, но не всегда объясняет механизм.','Вывод содержит свидетельства, метод проверки и оставшуюся неопределённость.'],
('После увеличения пула задержки пропали. Доказана ли утечка соединений?', 'Нет. Увеличенный пул мог лишь отложить её проявление или компенсировать нормальный рост параллелизма. Нужны сведения о получении/возврате соединений, удержании и повторяемости поведения.'),
[('https://sre.google/sre-book/effective-troubleshooting/','Google SRE · Effective Troubleshooting')])
add('08-prometheus-grafana','Где работают Prometheus, Grafana и OpenTelemetry','Размещаем инструменты на уже понятном пути данных. Смотрим настоящие интерфейсы и отделяем сбор, хранение, запросы, отображение и уведомления.',[
('roles','Одна задача — несколько компонентов',p('К этому моменту у нас есть потребность: регулярно получать измерения, сохранять историю, задавать вопросы к данным и разбирать отдельные операции. Теперь инструмент можно оценить по той части задачи, которую он выполняет.')+table(['Компонент','Основная роль в учебной схеме','Граница роли'],[['Приложение и инструментация','Создать измерения, события и spans','Само наличие /metrics не сохраняет историю вне процесса.'],['Prometheus','Собрать метрики, хранить ряды, выполнять PromQL и правила','Не заменяет журнал транзакций и хранилище подробных логов.'],['Grafana','Выполнять запросы к источникам и показывать данные','Данные панели зависят от источника, запроса и окна.'],['OpenTelemetry','Инструментация, контекст и передача телеметрии','Само по себе не является готовым хранилищем и интерфейсом расследования.'],['Collector','Получить, обработать и направить телеметрию','Маршрут данных настраивается; это не волшебная автодиагностика.'],['Alertmanager','Обрабатывать уведомления от alerting rules Prometheus','Доставка сообщения и вычисление условия — разные этапы.']])+p('Grafana также имеет собственную систему правил и уведомлений, а её экосистема включает отдельные продукты хранения. Это не меняет смысл приведённой схемы: сначала называем конкретный компонент и его роль, затем читаем связи.')),
('pull','Как измерение попадает в Prometheus',p('В обычной pull-схеме приложение предоставляет HTTP endpoint с текущими метриками. Prometheus периодически запрашивает его — такой опрос называется <strong>scrape</strong>. Результаты становятся наблюдениями во времени. Приложение не обязано знать, кто именно прочитал endpoint.')+'''<div class="interactive scrape" data-scrape><div class="widget-head"><b>Pull-сбор · направление запроса и данных</b><button data-scrape-step>Следующий шаг →</button></div><div class="scrape-route"><div><b>Приложение</b><code>/metrics</code></div><div class="scrape-arrow">← HTTP GET</div><div><b>Prometheus</b><code>scrape → samples</code></div><div class="scrape-arrow">← запрос</div><div><b>Grafana</b><code>панель</code></div></div><p class="widget-detail" aria-live="polite">1. Приложение обновляет свои измерения при обработке запросов.</p></div>'''+p('HTTP-запрос при сборе направлен от Prometheus к приложению, а числовые данные возвращаются в ответе. Grafana затем запрашивает Prometheus. Стрелка «приложение → Prometheus» допустима как направление данных, но без пояснения может создать ошибочное представление о направлении сетевого вызова.')+p('Есть и другие способы приёма и передачи метрик. В первом модуле рассматриваем один маршрут, чтобы не смешивать знакомство со смыслом телеметрии и все варианты интеграции.')),
('prom','Интерфейс Prometheus на нашем стенде',shot('prometheus-query','Запрос метрик учебного API в Prometheus','Настоящий Prometheus читает endpoint /metrics. Значения относятся к моменту съёмки и включают демонстрационные запросы; они не обязаны равняться отдельному прогону из 20 запросов.')+p('В интерфейсе запроса можно увидеть ряды, соответствующие имени метрики и выбранным признакам. Поле <code>status</code> разделяет успешные и ошибочные ответы. Подробный синтаксис селекторов, счётчиков и функций скорости будет разобран в модуле о PromQL.')+p('Наличие рядов не означает, что все обращения пользователей измерены. В учебной программе учитывается только <code>/products</code>; запросы к <code>/health</code>, <code>/docs</code> и <code>/metrics</code> в её счётчик не входят. Это решение видно в исходном коде и определяет смысл графика.')),
('grafana','Grafana показывает результат запроса',shot('grafana-dashboard','Дашборд Grafana с данными учебного API','Две верхние панели показывают количества с запуска процесса, нижние — запросы в секунду и среднюю длительность за скользящее минутное окно. Это четыре разные величины.')+p('Панель определяется источником, запросом, временным диапазоном и способом отображения. Одну и ту же метрику можно показать как последнее значение, линию или таблицу. Ошибка в запросе останется ошибкой и в аккуратно оформленном графике.')+p('Например, счётчик с запуска нельзя подписать «запросов за пять минут», не выполнив соответствующий расчёт. Среднюю длительность нельзя подписать p95. На сохранённом дашборде подписи указывают используемые величины; JSON конфигурации находится в архиве стенда.')+note('Техническое приложение к теме','Для чтения этой главы устанавливать Grafana и Prometheus не требуется. Скриншоты объясняют роли. Желающие могут запустить готовый демонстрационный Compose; устройство конфигураций разбирается в следующих модулях.')),
('architecture','Полная схема — ориентир для дальнейшего изучения',shot('prometheus-architecture','Официальная архитектура Prometheus','Кадр официальной страницы. Сейчас достаточно найти instrumented targets, Prometheus, запросы и визуализацию; остальные элементы понадобятся в отдельных главах.')+p('Дальше справочник последовательно расширяет учебный проект: типы метрик и labels, сбор, PromQL, дашборды, правила уведомлений и корреляция сигналов. Exporters зависимостей появятся после того, как будет понятно, какой вопрос закрывает каждый показатель.')+p('Pushgateway не нужно автоматически добавлять ко всем приложениям. Он решает определённые сценарии, а обычный долгоживущий HTTP-сервис обычно можно опрашивать напрямую. Подробности вынесены в модуль про сбор, чтобы выбор следовал из задачи.'))],
['Программа создаёт наблюдения; система сбора получает их и сохраняет историю.','Grafana выполняет запросы к источникам: смысл панели задаётся запросом.','OpenTelemetry и Collector помогают получать и передавать телеметрию, но не заменяют всю систему наблюдаемости.'],
('Приложение отдаёт /metrics, Grafana установлена, но источник не настроен. Появится история автоматически?', 'Нет. Нужен путь сбора и хранения, затем источник данных и запрос Grafana. Каждый участок проверяют отдельно.'),
[('https://prometheus.io/docs/introduction/overview/','Prometheus · Overview'),('https://grafana.com/docs/grafana/latest/fundamentals/','Grafana · Introduction'),('https://opentelemetry.io/docs/what-is-opentelemetry/','What is OpenTelemetry?')])
add('09-praktika','Практика: от жалобы к проверяемому выводу','Запускаем знакомый Python-проект, выполняем контролируемые запросы, сохраняем исходные данные и составляем собственный разбор. Prometheus для обязательной части не нужен.',[
('start','Подготовка и первый запуск',p('Скачайте архив и распакуйте его в отдельную рабочую папку. Внутри находится <code>telemetry-lab</code> с приложением, скриптом эксперимента и инструкцией. Требуется Python 3.12; установка зависимостей выполняется один раз в окружение проекта.')+p('<a class="primary" href="../assets/telemetry-lab.zip" download>Скачать учебный проект ↓</a>')+'''<div class="os-commands"><div class="controls" role="group" aria-label="Операционная система"><button data-os="unix" aria-pressed="true">macOS / Linux</button><button data-os="windows" aria-pressed="false">Windows · PowerShell</button></div><div data-command="unix">'''+code(r'''cd telemetry-lab
python3 -m venv .venv
source .venv/bin/activate
python -m pip install -r requirements.txt
python -m uvicorn app:app --host 127.0.0.1 --port 8015''','Терминал · из папки проекта')+'''</div><div data-command="windows" hidden>'''+code(r'''cd telemetry-lab
py -3.12 -m venv .venv
.\.venv\Scripts\python.exe -m pip install -r requirements.txt
.\.venv\Scripts\python.exe -m uvicorn app:app --host 127.0.0.1 --port 8015''','PowerShell · активация не требуется')+'''</div></div>'''+p('Терминал с Uvicorn оставьте открытым: в нём работает сервер. Откройте <code>http://127.0.0.1:8015/lab</code>. Кнопки выполняют настоящие HTTP-запросы. Swagger доступен по <code>/docs</code>, проверка процесса — по <code>/health</code>.')+p('Если окружения и зависимости пока непривычны, используйте <a href="../../mdk0101-razrabotka-modulei/lessons/02-struktura-python-proekta/index.html">материал о структуре Python-проекта</a>. Перед экспериментом достаточно понять: сервер работает в одном терминале, клиент запускается отдельно.')),
('code','Как внесена задержка и ошибка',code('''await stage("validate", 0.01)
try:
    await stage("dependency.wait (simulated)",
                3.0 if scenario == "slow" else 0.06)
    if scenario == "error":
        raise TimeoutError("Simulated dependency timeout; no database is connected")
    await stage("serialize", 0.01)
except TimeoutError:
    status = 500
    exception_text = traceback.format_exc()''','Фрагмент app.py · управляемые сценарии','app.py')+p('<code>asyncio.sleep</code> моделирует ожидание: корутина приостанавливается, и цикл событий может выполнять другую работу. Это не нагрузочный CPU-тест и не настоящая задержка SQL. В сценарии slow меняется только ожидание; в error действительно поднимается исключение, которое приложение превращает в HTTP 500.')+p('Функция <code>stage</code> измеряет интервал через <code>time.perf_counter()</code>. Этот таймер подходит для длительностей. Отдельно через <code>datetime.now(timezone.utc)</code> записывается календарное время события. Нельзя вычитать perf_counter одного процесса из отметки времени другой машины: это разные шкалы.')+shot('fastapi-swagger','Маршруты учебного API в Swagger','Документация создана самим FastAPI. Параметр scenario имеет три допустимых значения; переключение определяет воспроизводимый сценарий.')),
('blind','Этап A · наблюдение без общей истории',p('Нажмите fast, затем slow, затем error. Для каждого сохраните статус и длительность. После этого ответьте: сколько операций прошло за предыдущие сутки? Какая доля пользователей столкнулась с задержкой? Стало ли приложение медленнее, чем вчера?')+p('У локального стенда таких сведений нет. Три ручных запроса описывают только три выполненных опыта. Это не призыв игнорировать логи: это проверка границ наблюдения. Если нужная история не собиралась, её отсутствие нужно записать в вывод, а не заменить предположением.')+case('Узкий health-check',p('Выполните error на /products, затем откройте /health. Объясните, почему второй запрос успешен.'),p('/health проверяет только возможность выполнить простой обработчик процесса. Он не выполняет сценарий /products и не проверяет ту же зависимость. Ошибка одного маршрута не обязана делать весь процесс недоступным.'))),
('measure','Этап B · один и тот же эксперимент',p('Откройте второй терминал в распакованной папке. Запустите скрипт тем же Python из окружения.')+code(r'''# macOS / Linux
.venv/bin/python experiment.py

# Windows PowerShell
.\.venv\Scripts\python.exe experiment.py''','Клиент эксперимента · сервер продолжает работать','experiment.py')+p('Скрипт последовательно отправляет двадцать запросов и пишет <code>results/requests.csv</code>, <code>summary.json</code> и <code>events.json</code>. HTTP 500 учитывается как результат запроса, а не прерывает эксперимент. Поле <code>client_ms</code> измеряет клиентский интервал; <code>handler_ms</code> берётся из ответа сервера.')+ul(['Проверьте количество строк и ожидаемую последовательность: slow на 7-м и 17-м запросах, error на 13-м.','Вычислите долю HTTP 500 и долю запросов дольше секунды. Укажите знаменатель.','Сравните среднее и p95. Запишите метод расчёта и объясните разницу.','Найдите request_id медленного запроса в events.json; сопоставьте длительность с этапами.','Для ошибочного запроса найдите exception. Объясните, что известно о причине именно в этой модели.'])+note('Повторяемость не означает одинаковые миллисекунды','Сценарии и ожидаемые статусы детерминированы. Реальное планирование, сеть и нагрузка машины влияют на длительности. Сравнивайте закономерность и исходные строки, а не требуйте точного совпадения со скриншотом.')),
('checks','Что считать готовой работой',table(['Результат','Проверка'],[['Воспроизводимый запуск','Другой человек может запустить архив по вашей команде.'],['Исходные измерения','Сохранены все 20 строк, статусы и единицы времени.'],['Верные расчёты','Доля ошибок, среднее и p95 привязаны к одной выборке.'],['Связь сигналов','Для выбранного запроса связаны ответ, событие и этапы.'],['Ограничения вывода','Симуляция зависимости, маленькая выборка и один процесс названы явно.'],['Инженерный отчёт','Есть наблюдения, гипотеза, проверка и следующий вопрос.']])+p('<a href="../assets/investigation.md" download>Скачать бланк отчёта</a>. После основного опыта измените одну величину — например, число slow-запросов в сценарии. До запуска предскажите, что изменится в среднем и p95, затем проверьте на новом CSV. Не меняйте сразу задержку, число запросов и метод расчёта: иначе причины различий смешаются.')),
('troubleshooting','Если опыт не запускается',table(['Симптом','Что проверить'],[['No module named fastapi','Зависимости установлены тем же Python, которым запускается Uvicorn.'],['Address already in use','Порт 8015 занят. Выберите другой порт и передайте experiment.py --base http://127.0.0.1:НОВЫЙ_ПОРТ.'],['Connection refused','Сервер работает и адрес клиента совпадает с --host/--port.'],['В /events есть лишние записи','Консоль и Swagger тоже вызывают /products. experiment.py отбирает свои события по request_id.'],['После перезапуска пустая история','Учебный процесс держит ограниченный журнал в памяти. CSV предыдущего прогона сохраняется на диске.'],['В Grafana сначала нет линии','Дополнительному стенду нужны успешные scrape и минимум два наблюдения для скорости.']])),
('next','Что изучать дальше',p('Мы сформулировали вопросы к работающему сервису и проверили, какие данные на них отвечают. Следующий модуль начнётся с устройства метрики: имя, единица, timestamp, labels и sample. Затем появятся Counter, Gauge и Histogram, а уже после них — запросы и графики.')+p('Полная карта раздела находится в оглавлении. Неготовые главы обозначены как план и не ведут на пустые страницы. Первая тема завершена практикой: к дальнейшему изучению можно переходить, когда вы можете объяснить опыт по исходным данным.'))],
['В одном терминале работает сервер, в другом запускается клиент.','Сохранённые результаты привязаны к конкретному прогону.','Вывод должен учитывать границы модели и точки измерения.'],
('Почему в Prometheus запросов больше двадцати, а в вашем CSV двадцать?', 'Счётчик приложения включает и запросы из консоли/Swagger. CSV описывает только выбранный запуск experiment.py. Это разные области учёта, а не обязательно ошибка сбора.'),
[('https://fastapi.tiangolo.com/tutorial/first-steps/','FastAPI · First steps'),('https://docs.python.org/3/library/time.html#time.perf_counter','Python · perf_counter'),('https://docs.python.org/3/library/asyncio-task.html#asyncio.sleep','Python · asyncio.sleep')])
# Layout shared by chapters. Authored content stays in the document without JS.
FONT='https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Literata:ital,opsz,wght@0,7..72,600;0,7..72,700;1,7..72,400&family=Pixelify+Sans:wght@500;600;700&family=Roboto+Mono:wght@400;500;700&display=swap'
def layout(title,body,number=None):
 prefix='../' if number else ''
 home=prefix+'index.html'
 nav=''.join(f'<a href="{prefix}temy/{c["slug"]}.html"'+(' aria-current="page"' if number==i+1 else '')+f'>1.{i+1} {c["title"]}</a>' for i,c in enumerate(CH))
 # Chapter URLs are relative to temy, not to root.
 if number: nav=nav.replace('../temy/','')
 return f'''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#302330"><meta name="description" content="{escape(title)}. Подробный справочник Макарова М. Н.: объяснения, измерения, интерактивные схемы и реальные скриншоты."><title>{escape(title)} · Наблюдаемость · Макаров М. Н.</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="{FONT}" rel="stylesheet"><link rel="stylesheet" href="{prefix}styles.css"><script src="{prefix}assets/experiment-data.js" defer></script><script src="{prefix}book.js" defer></script></head><body>
<a class="skip" href="#main">К содержанию</a><div class="progress" aria-hidden="true"><span></span></div>
<header class="topbar"><a class="brand" href="{home}"><b>∿</b><span>Метрики и<br>наблюдаемость</span></a><div class="top-links"><a href="{prefix}../index.html">Все дисциплины</a><a href="https://python-theory-makarov.vercel.app/" target="_blank" rel="noreferrer">Справочник Python ↗</a></div><details class="chapter-menu"><summary>Главы темы 1</summary><nav aria-label="Главы первой темы">{nav}</nav></details></header>
<div class="book"><div class="book-body"><aside class="spine" aria-hidden="true"><span>Наблюдаемость / Метрики · Логи · Трассы / Макаров М. Н.</span></aside><main class="leaf" id="main"><div class="running"><a href="{home}">Практический справочник</a><span>{'Глава 1.'+str(number) if number else 'Макаров Максим Николаевич'}</span></div>{body}<footer><a href="{home}">К оглавлению ↑</a><span>Автор: Макаров Максим Николаевич</span><a href="{prefix}SOURCES.md">Источники и съёмка</a></footer></main></div></div>
<dialog id="image-dialog" aria-label="Увеличенный скриншот"><form method="dialog"><button aria-label="Закрыть изображение">Закрыть ×</button></form><img alt=""><p></p></dialog></body></html>'''
for i,c in enumerate(CH,1):
 body=f'<header class="chapter-head"><span class="chapter-num">1.{i}</span><h1>{c["title"]}</h1><p class="lead">{c["lead"]}</p></header>'
 body+='<dl class="passport"><div><dt>Раздел</dt><dd>Основы наблюдаемости</dd></div><div><dt>Уровень</dt><dd>С нуля · Python знаком</dd></div><div><dt>Как изучать</dt><dd>Читать, проверять, повторять</dd></div><div><dt>Опора</dt><dd>Один API и его данные</dd></div></dl>'
